\newcommand{\HH}{\mathbb{H}}
\newcommand{\RR}{\mathbb{R}}
\newcommand{\CC}{\mathbb{C}}
\newcommand{\OO}{\mathbb{O}}
\newcommand{\HP}{\mathbb{HP}}
\newcommand{\Real}{\operatorname{Re}}
\newcommand{\norm}[1]{\left\lVert #1 \right\rVert}

\title{The Quaternionic Hermitian Witness Reconstructs the Fibres of the Hopf
Fibration $S^7 \to S^4$}
\author{Aristotle}
\date{July 13, 2026}

\begin{document}

\begin{abstract}
The Hopf fibrations are the four exceptional sphere bundles organised by the
real composition (normed division) algebras $\RR,\CC,\HH,\OO$. We study the
quaternionic Hopf fibration $S^3 \to S^7 \to S^4$ through a single algebraic
device: the Hermitian inner product $\lambda = \bar q\,q' + \bar r\,r'$ of two
unit vectors $a=(q,r)$ and $b=(q',r')$ in $\HH^2$. We prove that this
\emph{witness} detects, bounds, and reconstructs the fibre structure exactly.
Our central result is an unconditional polynomial identity in eight quaternionic
variables which, on the unit sphere, specialises to the squared-distance
identity $\norm{q'-q\lambda}^2 + \norm{r'-r\lambda}^2 = 1 - \norm{\lambda}^2$.
From this single identity we deduce a Cauchy--Schwarz bound $\norm{\lambda}\le 1$;
a forward statement that $b = a\cdot\mu$ implies $\lambda=\mu$; and a
reconstruction statement that $\norm{\lambda}=1$ implies $b = a\cdot\lambda$.
Packaging these shows that the fibre through a fixed unit vector is a principal
homogeneous space for the unit quaternions $S^3$ acting on the right, with right
multiplication and the witness mutually inverse on the sphere. The only
structural departure from the complex case is that noncommutativity forces the
connecting phase to act on the right. The argument uses only two facts ---
multiplicativity of the quaternionic norm and the order-reversing property of
conjugation --- the two axioms of a composition algebra.
\end{abstract}

\maketitle

\section{Introduction}

The Hopf fibration $S^1 \hookrightarrow S^3 \to S^2$, discovered by Hopf in
1931, is the prototypical nontrivial fibre bundle and a cornerstone of algebraic
topology, generating $\pi_3(S^2)\cong\mathbb{Z}$. It admits exactly three higher
analogues, one for each remaining real composition algebra:
\[
S^1 \to S^3 \to S^2\ (\CC), \qquad
S^3 \to S^7 \to S^4\ (\HH), \qquad
S^7 \to S^{15} \to S^8\ (\OO).
\]
The correspondence between these fibrations and the normed division algebras
$\RR,\CC,\HH,\OO$ of dimensions $1,2,4,8$ is tied to Hurwitz's theorem and, via
the Hopf invariant one problem, to Adams's theorem.

This paper isolates a purely algebraic mechanism, the \emph{Hermitian
inner-product witness}, that recovers the fibre structure of the quaternionic
Hopf fibration elementarily. The philosophy is that a single device --- the
inner product of two unit vectors --- serves simultaneously as a detector of
fibre membership, a bound certifying that fibre-mates are the extremal case, and
a reconstructor returning the exact group element connecting two fibre-mates.
Over $\CC$ this is classical; our contribution is to carry the device verbatim
to the quaternions, where noncommutativity introduces exactly one new
phenomenon: the connecting phase must act on the \emph{right}.

\subsection{Contributions}
\begin{enumerate}
  \item An unconditional polynomial identity (Theorem~\ref{thm:uncond}) valid
    for all $q,r,q',r'\in\HH$, requiring no normalisation.
  \item The squared-distance identity (Theorem~\ref{thm:dist}) on the unit
    sphere: $\norm{q'-q\lambda}^2 + \norm{r'-r\lambda}^2 = 1-\norm{\lambda}^2$.
  \item A Cauchy--Schwarz bound (Theorem~\ref{thm:cs}): $\norm{\lambda}\le 1$.
  \item A forward reconstruction (Theorem~\ref{thm:fwd}): $b=a\cdot\mu
    \Rightarrow \lambda=\mu$.
  \item A fibre reconstruction (Theorem~\ref{thm:recon}): $\norm{\lambda}=1
    \Rightarrow b = a\cdot\lambda$.
  \item A torsor / fibre correspondence (Theorem~\ref{thm:torsor}).
\end{enumerate}

\section{Preliminaries}

\subsection{Quaternions}
The quaternions $\HH$ form the four-dimensional real associative algebra with
basis $1,i,j,k$ and Hamilton's relations $i^2=j^2=k^2=ijk=-1$. A quaternion is
$q=w+xi+yj+zk$ with $w,x,y,z\in\RR$. The conjugate is $\bar q = w-xi-yj-zk$, and
the norm satisfies $\norm{q}^2 = q\bar q = \bar q q = w^2+x^2+y^2+z^2$.
Multiplication is associative but not commutative.

\begin{lemma}[Composition-algebra axioms]\label{lem:ca}
For all $p,q\in\HH$:
\begin{enumerate}
  \item (Norm multiplicativity) $\norm{pq}^2 = \norm{p}^2\norm{q}^2$.
  \item (Conjugation antihomomorphism) $\overline{pq} = \bar q\,\bar p$.
\end{enumerate}
In particular $\bar q\,(q\mu) = (\bar q q)\mu = \norm{q}^2\mu$, whereas
$\bar q\,(\mu q)$ does not simplify.
\end{lemma}

\subsection{The quaternionic Hopf fibration}
The total space is $S^7 = \{(q,r)\in\HH^2 : \norm{q}^2+\norm{r}^2 = 1\}$. The
group $S^3 = \{\mu\in\HH : \norm{\mu}=1\}$ acts freely on $S^7$ by right
multiplication $(q,r)\cdot\mu = (q\mu,r\mu)$; this is well defined by norm
multiplicativity. The orbit space is $\HP^1\cong S^4$, and the projection
$S^7\to S^4$ is the quaternionic Hopf fibration with fibre $S^3$. Two points lie
on a common fibre iff they are right-proportional by a unit quaternion.

\begin{definition}[Hermitian witness]
For $a=(q,r)$ and $b=(q',r')$ in $\HH^2$, the \emph{witness} is
$\lambda(a,b) = \bar q\,q' + \bar r\,r' \in \HH$.
\end{definition}

\section{Main results}

Throughout, fix $q,r,q',r'\in\HH$ and write $\lambda = \bar q q' + \bar r r'$.

\begin{theorem}[Unconditional algebraic identity]\label{thm:uncond}
For all $q,r,q',r'\in\HH$,
\[
\norm{q'-q\lambda}^2 + \norm{r'-r\lambda}^2
= \big(\norm{q'}^2+\norm{r'}^2\big) - 2\norm{\lambda}^2
  + \big(\norm{q}^2+\norm{r}^2\big)\norm{\lambda}^2 .
\]
\end{theorem}

\begin{proof}
Expand each squared norm via $\norm{u-v}^2 = \norm{u}^2 - 2\Real(\bar u v)
+ \norm{v}^2$. The cross terms are
\[
-2\Real\big(\overline{q'}(q\lambda)\big) - 2\Real\big(\overline{r'}(r\lambda)\big)
= -2\Real\big((\overline{q'}q + \overline{r'}r)\lambda\big)
= -2\Real(\bar\lambda\lambda) = -2\norm{\lambda}^2,
\]
using $\overline{q'}q + \overline{r'}r = \bar\lambda$ and
$\Real(\bar\lambda\lambda)=\norm{\lambda}^2$. The quadratic terms give
$\norm{q\lambda}^2 + \norm{r\lambda}^2 = (\norm{q}^2+\norm{r}^2)\norm{\lambda}^2$
by Lemma~\ref{lem:ca}. Collecting terms yields the identity, which is
polynomial in the sixteen real coordinates.
\end{proof}

\begin{theorem}[Squared-distance identity]\label{thm:dist}
If $\norm{q}^2+\norm{r}^2 = 1$ and $\norm{q'}^2+\norm{r'}^2 = 1$, then
\[
\norm{q'-q\lambda}^2 + \norm{r'-r\lambda}^2 = 1 - \norm{\lambda}^2 .
\]
\end{theorem}

\begin{proof}
Substitute both unit-norm hypotheses into Theorem~\ref{thm:uncond}: the right
side becomes $1 - 2\norm{\lambda}^2 + \norm{\lambda}^2 = 1 - \norm{\lambda}^2$.
\end{proof}

\begin{theorem}[Cauchy--Schwarz]\label{thm:cs}
If $a,b$ are unit vectors, then $\norm{\lambda}\le 1$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:dist}, $1-\norm{\lambda}^2$ is a sum of two squared norms,
hence nonnegative; so $\norm{\lambda}^2\le 1$ and $\norm{\lambda}\le 1$.
\end{proof}

\begin{theorem}[Witness of a proportional pair]\label{thm:fwd}
If $\norm{q}^2+\norm{r}^2 = 1$ and $q'=q\mu$, $r'=r\mu$, then $\lambda=\mu$.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:ca}, $\lambda = \bar q(q\mu) + \bar r(r\mu) = \norm{q}^2\mu +
\norm{r}^2\mu = (\norm{q}^2+\norm{r}^2)\mu = \mu$. The collapse
$\bar q(q\mu)=\norm{q}^2\mu$ requires $\mu$ on the right.
\end{proof}

\begin{theorem}[Reconstruction]\label{thm:recon}
If $a,b$ are unit vectors and $\norm{\lambda}=1$, then $q'=q\lambda$ and
$r'=r\lambda$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:dist}, $\norm{q'-q\lambda}^2 + \norm{r'-r\lambda}^2 =
1-\norm{\lambda}^2 = 0$. A sum of nonnegative reals vanishes only if each does,
so $q'=q\lambda$ and $r'=r\lambda$.
\end{proof}

\begin{theorem}[Right action preserves the sphere]\label{thm:pres}
If $\norm{q}^2+\norm{r}^2=1$ and $\norm{\mu}=1$, then
$\norm{q\mu}^2+\norm{r\mu}^2=1$.
\end{theorem}

\begin{proof}
$\norm{q\mu}^2+\norm{r\mu}^2 = \norm{q}^2\norm{\mu}^2 + \norm{r}^2\norm{\mu}^2 =
\norm{q}^2+\norm{r}^2 = 1$ by Lemma~\ref{lem:ca}.
\end{proof}

\begin{theorem}[Fibre correspondence / torsor structure]\label{thm:torsor}
Fix a unit vector $a=(q,r)$. Then:
\begin{enumerate}
  \item For every unit quaternion $\mu$, the point $a\cdot\mu$ is a unit vector
    and $\lambda(a, a\cdot\mu)=\mu$.
  \item For every unit vector $b=(q',r')$ with $\norm{\lambda(a,b)}=1$, we have
    $b = a\cdot\lambda(a,b)$.
\end{enumerate}
Consequently $\mu\mapsto a\cdot\mu$ and $b\mapsto\lambda(a,b)$ are mutually
inverse bijections between $S^3$ and the fibre through $a$; in particular the
fibre is a principal homogeneous space for $S^3$ acting on the right.
\end{theorem}

\begin{proof}
Part (1) combines Theorem~\ref{thm:pres} with Theorem~\ref{thm:fwd}. Part (2) is
Theorem~\ref{thm:recon}. The maps are mutually inverse: from $\mu$, going out
then back gives $\lambda(a,a\cdot\mu)=\mu$; from a fibre point $b$, coming back
then out gives $a\cdot\lambda(a,b)=b$. Freeness follows since $a\cdot\mu =
a\cdot\mu'$ forces $\mu=\lambda(a,a\cdot\mu)=\lambda(a,a\cdot\mu')=\mu'$.
\end{proof}

\section{The role of noncommutativity}

The complex analogue (for $S^1\to S^3\to S^2$) is identical in form, with
$\lambda = \bar z z' + \bar w w'\in\CC$; commutativity hides the side of the
phase. Over $\HH$ the distinction is essential and is the only structural change.
The decisive step is $\bar q(q\mu)=\norm{q}^2\mu$, which holds because
$\bar q q\in\RR$ is central but requires $\mu$ on the right. A left action would
produce $\bar q(\mu q)$, which does not simplify. Thus the composition-algebra
machinery forces the fibre to be a right $\HH$-line and the witness to return the
right-hand phase.

\section{Algorithms}

\textbf{Fibre-membership test.} Given unit $a,b$, compute
$\lambda=\bar q q'+\bar r r'$ and $\norm{\lambda}^2=\lambda\bar\lambda$; report
``same fibre, phase $\lambda$'' iff $\norm{\lambda}^2=1$. Cost $O(1)$ quaternion
operations, no divisions.

\textbf{Phase reconstruction.} For known fibre-mates, return $\mu=\bar q q' +
\bar r r'$ (Theorems~\ref{thm:fwd},~\ref{thm:recon}).

\textbf{Geodesic defect.} Return $1-\norm{\lambda}^2\ge0$, a similarity score on
the base $S^4=\HP^1$ that vanishes iff $a,b$ are fibre-mates
(Theorem~\ref{thm:dist}).

\section{Applications and discussion}

Unit quaternions model 3D rotations, so the witness is a division-free test for
whether two states in a two-quaternion register differ by a global right phase,
together with the exact phase --- useful in robotics, attitude control, and
graphics. The residual $1-\norm{\lambda}^2$ descends to a coordinate-free
chordal-type quantity on $S^4$. Since the proofs use only the two
composition-algebra axioms, the same skeleton applies to the complex fibration
verbatim, and is conjectured to apply to the octonionic fibration $S^7\to
S^{15}\to S^8$ with a fixed bracketing of the projection. The identity is, in
effect, a certificate that its ambient algebra is a composition algebra, hinting
at an algebraic route to the Hurwitz dimensional restriction $1,2,4,8$.

\section{Conclusion}

A single quaternion --- the Hermitian inner product of two unit vectors in
$\HH^2$ --- bounds, detects, and reconstructs the fibres of the quaternionic
Hopf fibration $S^7\to S^4$. The mechanism is an unconditional algebraic identity
resting solely on the composition-algebra axioms, so it transfers across the
normed division algebras, with noncommutativity appearing only as the side on
which the connecting phase acts. The fibre through any unit vector is thereby a
right $S^3$-torsor whose exact ruler is the inner product.

\end{document}

