from __future__ import annotations
import math
from dataclasses import dataclass


@dataclass(frozen=True)
class Quaternion:
    """A real quaternion w + x i + y j + z k."""
    w: float
    x: float
    y: float
    z: float

    def __add__(self, o: "Quaternion") -> "Quaternion":
        return Quaternion(self.w + o.w, self.x + o.x, self.y + o.y, self.z + o.z)

    def __sub__(self, o: "Quaternion") -> "Quaternion":
        return Quaternion(self.w - o.w, self.x - o.x, self.y - o.y, self.z - o.z)

    def __mul__(self, o: "Quaternion") -> "Quaternion":
        a, b, c, d = self.w, self.x, self.y, self.z
        e, f, g, h = o.w, o.x, o.y, o.z
        return Quaternion(
            a * e - b * f - c * g - d * h,
            a * f + b * e + c * h - d * g,
            a * g - b * h + c * e + d * f,
            a * h + b * g - c * f + d * e,
        )

    def conj(self) -> "Quaternion":
        return Quaternion(self.w, -self.x, -self.y, -self.z)

    def norm_sq(self) -> float:
        return self.w**2 + self.x**2 + self.y**2 + self.z**2

    def norm(self) -> float:
        return math.sqrt(self.norm_sq())


def witness(q: Quaternion, r: Quaternion,
            qp: Quaternion, rp: Quaternion) -> Quaternion:
    """Hermitian inner-product witness lambda = conj(q)q' + conj(r)r'."""
    return q.conj() * qp + r.conj() * rp


def verify_identities(q, r, qp, rp) -> dict[str, float]:
    """Return the residuals of the three headline identities for one octuple."""
    lam = witness(q, r, qp, rp)
    uncond_lhs = (qp - q * lam).norm_sq() + (rp - r * lam).norm_sq()
    uncond_rhs = ((qp.norm_sq() + rp.norm_sq()) - 2 * lam.norm_sq()
                  + (q.norm_sq() + r.norm_sq()) * lam.norm_sq())
    return {
        "witness_norm": lam.norm(),
        "unconditional_residual": abs(uncond_lhs - uncond_rhs),
    }


if __name__ == "__main__":
    import random
    random.seed(7)
    rq = lambda: Quaternion(*(random.uniform(-2, 2) for _ in range(4)))
    for _ in range(4):
        print(verify_identities(rq(), rq(), rq(), rq()))

