def reconstruct_phase(q, r, qp, rp) -> tuple[Quaternion, float, float]:
    """Given fibre-mates, recover the right phase lambda and check q'=q*lam."""
    lam = witness(q, r, qp, rp)
    e1 = (qp - q * lam).norm()
    e2 = (rp - r * lam).norm()
    return lam, e1, e2


