def fibre_membership(q: Quaternion, r: Quaternion,
                     qp: Quaternion, rp: Quaternion,
                     tol: float = 1e-9) -> tuple[bool, Quaternion | None, float]:
    """Decide whether two unit vectors of H^2 share a quaternionic Hopf fibre.

    Returns (is_same_fibre, connecting_phase_or_None, defect), where the phase
    is the witness lambda and defect = 1 - ||lambda||^2 >= 0.
    """
    lam = witness(q, r, qp, rp)
    defect = 1.0 - lam.norm_sq()
