from __future__ import annotations
import math
from dataclasses import dataclass


@dataclass(frozen=True)
class Quaternion:
    """A real quaternion w + x i + y j + z k."""
    w: float
    x: float
    y: float
    z: float

    def __add__(self, o: "Quaternion") -> "Quaternion":
        return Quaternion(self.w + o.w, self.x + o.x, self.y + o.y, self.z + o.z)

    def __sub__(self, o: "Quaternion") -> "Quaternion":
        return Quaternion(self.w - o.w, self.x - o.x, self.y - o.y, self.z - o.z)

    def __mul__(self, o: "Quaternion") -> "Quaternion":
        a, b, c, d = self.w, self.x, self.y, self.z
        e, f, g, h = o.w, o.x, o.y, o.z
        return Quaternion(
            a * e - b * f - c * g - d * h,
            a * f + b * e + c * h - d * g,
            a * g - b * h + c * e + d * f,
            a * h + b * g - c * f + d * e,
        )

    def conj(self) -> "Quaternion":
        return Quaternion(self.w, -self.x, -self.y, -self.z)

    def norm_sq(self) -> float:
        return self.w**2 + self.x**2 + self.y**2 + self.z**2

    def norm(self) -> float:
        return math.sqrt(self.norm_sq())


def witness(q: Quaternion, r: Quaternion,
            qp: Quaternion, rp: Quaternion) -> Quaternion:
    """Hermitian inner-product witness lambda = conj(q)q' + conj(r)r'."""
    return q.conj() * qp + r.conj() * rp


def base_defect(q: Quaternion, r: Quaternion,
                qp: Quaternion, rp: Quaternion) -> float:
    """Chordal-type separation on the base S^4 = HP^1.

    Returns 1 - ||lambda||^2 in [0, 1]; it is 0 iff the points project to the
    same point of S^4 and grows toward 1 as the projections separate. By the
    squared-distance identity this equals the squared residual of q' from its
    projection q*lambda summed with that of r'.
    """
    lam = witness(q, r, qp, rp)
    return max(0.0, 1.0 - lam.norm_sq())

