"""Histogram of witness norms ||lambda|| for random unit vectors (all <= 1)."""
from __future__ import annotations
import math, random
import matplotlib.pyplot as plt


def qmul(a, b):
    aw, ax, ay, az = a; bw, bx, by, bz = b
    return (aw*bw - ax*bx - ay*by - az*bz,
            aw*bx + ax*bw + ay*bz - az*by,
            aw*by - ax*bz + ay*bw + az*bx,
            aw*bz + ax*by - ay*bx + az*bw)

def conj(a): return (a[0], -a[1], -a[2], -a[3])
def add(a, b): return tuple(x+y for x, y in zip(a, b))
def nsq(a): return sum(x*x for x in a)

def unit_vec():
    while True:
        q = tuple(random.uniform(-1, 1) for _ in range(4))
        r = tuple(random.uniform(-1, 1) for _ in range(4))
        n = math.sqrt(nsq(q) + nsq(r))
        if n > 1e-9:
            return tuple(x/n for x in q), tuple(x/n for x in r)

random.seed(1)
norms = []
for _ in range(5000):
    (q, r), (qp, rp) = unit_vec(), unit_vec()
    lam = add(qmul(conj(q), qp), qmul(conj(r), rp))
    norms.append(math.sqrt(nsq(lam)))

plt.figure(figsize=(7, 4))
plt.hist(norms, bins=50, color="#4c72b0", edgecolor="white")
plt.axvline(1.0, color="red", linestyle="--", label=r"Cauchy-Schwarz bound $\||\lambda\||=1$")
plt.xlabel(r"$\||\lambda\||$"); plt.ylabel("count")
plt.title("Witness norms for random unit-vector pairs stay <= 1")
plt.legend(); plt.tight_layout(); plt.savefig("viz_cauchy_schwarz.png", dpi=140)
print("saved viz_cauchy_schwarz.png")
